  </defs>

  <!-- sky -->
  <rect x="-20" y="-20" width="1320" height="760" fill="url(#sky)"/>

  <!-- sun -->
  <circle id="sunGlow" cx="1035" cy="165" r="165" fill="url(#sunGlowG)"/>
  <circle cx="1035" cy="165" r="46" fill="#fff6d9" opacity=".92" filter="url(#soft4)"/>

  <!-- clouds -->
  <g id="clouds" fill="#ffffff" opacity=".7">
    <g class="cloud" style="animation-duration:118s;animation-delay:-18s;">
      <ellipse cx="60" cy="150" rx="72" ry="26"/>
      <ellipse cx="10" cy="158" rx="52" ry="20"/>
      <ellipse cx="112" cy="160" rx="58" ry="19"/>
