      <ellipse cx="282" cy="104" rx="44" ry="15"/>
      <ellipse cx="243" cy="82" rx="34" ry="18"/>
    </g>
    <g class="cloud" style="animation-duration:142s;animation-delay:-96s;opacity:.6">
      <ellipse cx="420" cy="215" rx="86" ry="22"/>
      <ellipse cx="356" cy="222" rx="58" ry="17"/>
      <ellipse cx="486" cy="222" rx="62" ry="16"/>
    </g>
    <g class="cloud" style="animation-duration:170s;animation-delay:-140s;opacity:.5">
      <ellipse cx="700" cy="128" rx="64" ry="18"/>
      <ellipse cx="656" cy="136" rx="44" ry="14"/>
      <ellipse cx="748" cy="136" rx="46" ry="13"/>
    </g>
  </g>

  <!-- distant hills -->
  <path d="M -30 512 Q 140 400 300 470 Q 440 532 580 450 Q 720 372 860 452 Q 1000 530 1140 448 Q 1240 396 1310 462 L 1310 600 L -30 600 Z" fill="url(#hillFar)"/>
  <path d="M -30 542 Q 180 478 380 522 Q 560 562 740 518 Q 920 474 1100 528 Q 1215 560 1310 528 L 1310 640 L -30 640 Z" fill="url(#hillMid)"/>

  <!-- ground -->
  <rect x="-30" y="545" width="1340" height="220" fill="url(#ground)"/>
  <rect x="-30" y="500" width="1340" height="80" fill="url(#haze)"/>

  <!-- scrolling grass -->
  <g id="grassScroll"></g>

  <!-- alpaca -->
  <g id="alpaca" style="filter:drop-shadow(0 7px 9px rgba(46,74,54,.22))">
    <ellipse id="shadow" cx="632" cy="562" rx="152" ry="17" fill="#26452f" opacity=".26" filter="url(#soft9)"/>

    <!-- FAR legs -->
    <g class="leg" style="transform-origin:570px 426px;animation-delay:-0.2875s;">
      <path d="M555 426 C550 480 558 510 561.5 538 L578.5 538 C582 510 590 480 585 426 Z" fill="#dbb391"/>
      <rect x="559" y="536" width="21" height="24" rx="5" fill="#8a7060"/>
    </g>
    <g class="leg" style="transform-origin:722px 426px;animation-delay:-0.575s;">
      <path d="M710.5 426 C706.5 480 713 510 715 538 L729 538 C731 510 737.5 480 733.5 426 Z" fill="#dbb391"/>
      <rect x="713" y="536" width="18" height="24" rx="5" fill="#8a7060"/>
    </g>

    <!-- NEAR legs -->
    <g class="leg" style="transform-origin:546px 426px;animation-delay:-0.8625s;">
      <path d="M531 426 C526 480 534 510 537.5 538 L554.5 538 C558 510 566 480 561 426 Z" fill="#f6ddbb"/>
      <rect x="535" y="536" width="21" height="24" rx="5" fill="#6f5a4c"/>
    </g>
    <g class="leg" style="transform-origin:700px 426px;animation-delay:0s;">
      <path d="M688.5 426 C684.5 480 691 510 693 538 L707 538 C709 510 715.5 480 711.5 426 Z" fill="#f6ddbb"/>
      <rect x="691" y="536" width="18" height="24" rx="5" fill="#6f5a4c"/>
    </g>

    <!-- bobbing body -->
    <g id="bodyBob">

      <!-- tail -->
      <g id="tail">
        <circle cx="472" cy="380" r="21" fill="#f6ddbb"/>
        <circle cx="459" cy="398" r="17" fill="#f6ddbb"/>
        <circle cx="480" cy="359" r="15" fill="#f6ddbb"/>
        <circle cx="458" cy="380" r="14" fill="#e7c49f" opacity=".45"/>
      </g>

      <!-- body fleece -->
      <g id="body">
        <ellipse cx="622" cy="400" rx="116" ry="60" fill="#f6ddbb"/>
        <g fill="#f6ddbb">
          <circle cx="528" cy="372" r="30"/>
          <circle cx="556" cy="352" r="32"/>
          <circle cx="588" cy="342" r="30"/>
          <circle cx="620" cy="338" r="32"/>
          <circle cx="652" cy="342" r="30"/>
          <circle cx="682" cy="354" r="28"/>
          <circle cx="708" cy="372" r="26"/>
          <circle cx="508" cy="398" r="30"/>
          <circle cx="730" cy="392" r="30"/>
          <circle cx="737" cy="414" r="26"/>
          <circle cx="540" cy="436" r="26"/>
          <circle cx="575" cy="448" r="24"/>
          <circle cx="612" cy="452" r="24"/>
          <circle cx="650" cy="450" r="24"/>
          <circle cx="686" cy="442" r="22"/>
          <circle cx="716" cy="428" r="22"/>
        </g>
        <ellipse cx="620" cy="434" rx="110" ry="46" fill="url(#underShade)"/>
        <ellipse cx="604" cy="352" rx="92" ry="34" fill="url(#topLight)" filter="url(#soft9)"/>
      </g>

      <!-- neck -->
      <g id="neck">
        <path d="M688 402 C684 354 704 306 740 268 L766 292 C742 336 728 378 728 414 Z" fill="#f6ddbb"/>
        <g fill="#f6ddbb">
          <circle cx="694" cy="382" r="17"/>
          <circle cx="701" cy="352" r="16"/>
          <circle cx="713" cy="322" r="15"/>
          <circle cx="729" cy="294" r="13"/>
          <circle cx="752" cy="272" r="12"/>
        </g>
        <path d="M762 289 C741 332 730 376 731 409" fill="none" stroke="#e5bd98" stroke-width="10" stroke-linecap="round" opacity=".55"/>
      </g>

      <!-- head -->
      <g id="head">
        <path d="M738 262 C738 240 758 226 780 230 C800 234 814 250 814 266 C814 282 798 294 776 293 C752 292 738 280 738 262 Z" fill="#f6ddbb"/>
        <g fill="#f6ddbb">
          <circle cx="744" cy="242" r="13"/>
          <circle cx="757" cy="230" r="14"/>
          <circle cx="772" cy="224" r="13"/>
          <circle cx="788" cy="230" r="12"/>
          <circle cx="799" cy="241" r="11"/>
        </g>
        <ellipse cx="803" cy="275" rx="16" ry="13" fill="#eec6ad"/>
