    </g>
  </g>

  <!-- foreground grass -->
  <g id="fgScroll" filter="url(#soft4)" opacity=".95"></g>

  <!-- vignette -->
  <rect x="-20" y="-20" width="1320" height="760" fill="url(#vig)" pointer-events="none"/>
</svg>

<script>
(function () {
  var NS = 'http://www.w3.org/2000/svg';

  function mulberry32(a) {
    return function () {
      a |= 0; a = a + 0x6D2B79F5 | 0;
      var t = Math.imul(a ^ a >>> 15, 1 | a);
      t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
      return ((t ^ t >>> 14) >>> 0) / 4294967296;
    };
  }
  var rand = mulberry32(20240607);

  function el(name, attrs) {
    var n = document.createElementNS(NS, name);
    for (var k in attrs) n.setAttribute(k, attrs[k]);
    return n;
  }

  function buildGrass(target, count, yMin, yMax, sMin, sMax, cols, flowerRate, flowers) {
    for (var tile = 0; tile < 3; tile++) {
      for (var i = 0; i < count; i++) {
        var x = rand() * 640 + tile * 640;
        var t = rand();
        var y = yMin + t * (yMax - yMin);
        var s = sMin + t * (sMax - sMin);
        var g = el('g', { transform: 'translate(' + x.toFixed(1) + ' ' + y.toFixed(1) + ') scale(' + s.toFixed(2) + ')' });

        var blades = 3 + ((rand() * 2) | 0);
        for (var b = 0; b < blades; b++) {
          var ang = (rand() - 0.5) * 1.05;
          var len = 11 + rand() * 13;
          var tipX = Math.sin(ang) * len;
          var tipY = -Math.cos(ang) * len;
          var c1x = Math.sin(ang) * len * 0.35 - len * 0.14;
          var c1y = -Math.cos(ang) * len * 0.55;
          g.appendChild(el('path', {
            d: 'M0 0 Q ' + c1x.toFixed(1) + ' ' + c1y.toFixed(1) + ' ' + tipX.toFixed(1) + ' ' + tipY.toFixed(1),
            fill: 'none',
            stroke: cols[(rand() * cols.length) | 0],
            'stroke-width': (2.4 + rand() * 0.9).toFixed(1),
            'stroke-linecap': 'round',
            opacity: (0.72 + rand() * 0.28).toFixed(2)
          }));
        }
        target.appendChild(g);

        if (flowers && rand() < flowerRate) {
          var fc = ['#fff4e2', '#ffd9e0', '#ffe9a8', '#e8def9'][(rand() * 4) | 0];
          var f = el('g', { transform: 'translate(' + x.toFixed(1) + ' ' + (y - 8).toFixed(1) + ') scale(' + s.toFixed(2) + ')' });
          for (var p = 0; p < 5; p++) {
            var a2 = p / 5 * Math.PI * 2;
            f.appendChild(el('circle', {
              cx: (Math.cos(a2) * 3.1).toFixed(2),
              cy: (Math.sin(a2) * 3.1).toFixed(2),
              r: 2.3, fill: fc
            }));
          }
          f.appendChild(el('circle', { cx: 0, cy: 0, r: 1.7, fill: '#f5b94a' }));
          target.appendChild(f);
        }
      }
    }
  }

  buildGrass(document.getElementById('grassScroll'), 52, 552, 706, 0.62, 1.5,
    ['#52855c', '#45755a', '#63976a', '#38614b'], 0.11, true);

  buildGrass(document.getElementById('fgScroll'), 17, 660, 760, 1.5, 2.5,
    ['#35604a', '#2c5340', '#3f6d52'], 0.05, false);
})();
</script>
</body>
</html>
```
### Walk Cycle & Scene Mechanics

The animation focuses on a believable, continuous walking loop, with the body and ground working together.

- **Gait & body motion:** Four legs are split into near and far groups, each with staggered timing to create a natural walk. The body bobs, the neck sways, and the head nods slightly, while the tail and ears add secondary motion.
- **Treadmill-style ground:** The grass scrolls left at a steady pace, so the alpaca appears to walk in place. A soft shadow pulses beneath it, reinforcing contact with the ground.
- **Scene & depth:** A warm sky, distant hills, drifting clouds, and blurred foreground grass frame the alpaca without stealing focus.
---

**Optimization Tip:** You can adjust the walking speed by changing the 1.15s duration in the .leg and #bodyBob animations. Similarly, the grass scroll speed is controlled by the 9s and 4.6s values in #grassScroll and #fgScroll.
